<section class="jura-card"><h1>User Groups</h1><?php if (!empty($groups)): ?><table class="jura-table"><thead><tr><th>ID</th><th>Code</th><th>Name</th><th>Description</th><th>System</th></tr></thead><tbody><?php foreach($groups as $g): ?><tr><td><?=e($g['id'])?></td><td><?=e($g['code'])?></td><td><?=e($g['name'])?></td><td><?=e($g['description'])?></td><td><?=!empty($g['is_system'])?'Yes':'No'?></td></tr><?php endforeach;?></tbody></table><?php else: ?><p>No groups.</p><?php endif; ?></section>
